-- Speglar det som lades på databasen 2026-09-15 via apply_migration:
--   zh_catalogue_chunks_part_01..06         (smc-kat-zh-a.pdf, 126 stycken i knowledge_chunks;
--                                            del 3–6 med sammanpressade blanksteg -- se scripts/ingest-catalogues.py)
--   zh_order_code_from_catalogue_part_01..07 (backup, schema, familj, parametrar, värden, 126 regler,
--                                            dokumentkarta, kategori vacuum, produktspecar)
-- Fingeravtryck efter körning, identiska med modellen (scripts/fingerprint-rules.ts zh):
--   regler  126  md5 efb55b6577d0c8a29d2479ec6f6d9bb6   villkor fa72d24973ee5ae0902a08b9eff74b8e
--   värden  74   md5 0a531de75266abe03133a8e45f9598b1
--   schema       md5 d06da542688f29f854dd8601edf1185d
-- Verifierat live: /sv/configurator/zh bygger ZH10DSA-06-06-08 (nyckelns exempel, sida 749)
-- och säger "EXH-port 08 — välj den" innan EXH är vald.
-- Stycketexterna finns inte här: de läses in med scripts/ingest-catalogues.py
-- (filen finns i docs/kataloger/) -- den här filen speglar bara familjen.
--
-- ZH: beställnyckeln enligt SMC Vacuum Ejector ZH Series, Body Ported Type/Box Type.
-- GENERERAD ur src/lib/catalog/zh.ts -- redigera inte för hand.
--
-- Rättar familjen zh, som hette "ZH Valve", låg i kategorin valve och hade
-- mallen 'ZH-{size}-{function}-{voltage}-{connection}' med ventilparametrar.
-- ZH är en vakuumejektor. SMC:s kod är
-- ZH{munstycke}{kropp}{vakuum}A-{sup}-{vac}-{exh}{tillbehör}, t.ex.
-- ZH10DSA-06-06-08 (sida 749) och ZH10BSA-06-06 (sida 750).
--
-- Katalogen hämtades 2026-09-15 (smc-kat-zh-a.pdf, 126 stycken i
-- knowledge_chunks); smc-kat-zh.pdf är helrostfria ZH-X267, en egen nyckel.

begin;

create schema if not exists backup;
create table if not exists backup.zh_before_20260915 as
  select 'param' as sort, p.id::text as id, p.param_key as k, p.label as v
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'zh'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'zh'
  union all
  select 'family', f.id::text, f.slug, coalesce(f.order_code_template, '')
  from configurator_families f where f.slug = 'zh';

